async function run() {
  console.log('\n' + '═'.repeat(60));
  console.log('  SEEDING 3 NEW COURSES');
  console.log('═'.repeat(60));

  await mongoose.connect(MONGO_URI);
  console.log('\n  ✅ Connected\n');

  const Course = mongoose.connection.models.Course ||
    mongoose.model('Course', new mongoose.Schema({}, { strict: false, collection: 'courses' }));

  for (const courseData of COURSES) {
    const existing = await Course.findOne({
      $or: [
        { slug: courseData.slug },
        { title: courseData.title }
      ]
    });

    let totalWords = 0;
    for (const m of courseData.modules) {
      for (const l of m.lessons) {
        totalWords += countWords(l.content);
      }
    }

    if (existing) {
      await Course.updateOne({ _id: existing._id }, { $set: courseData });
      console.log(`  ✏️  UPDATED: ${courseData.title.substring(0, 55)}`);
    } else {
      await Course.create(courseData);
      console.log(`  ✅ CREATED: ${courseData.title.substring(0, 55)}`);
    }
    console.log(`     ${courseData.ceHours}CE | ${totalWords.toLocaleString()} words | ${courseData.modules.length} modules\n`);
  }

  await mongoose.disconnect();
  console.log('✅ Done\n');
}

run().catch(err => { console.error('❌', err.message); process.exit(1); });
